<div class="d-flex justify-content-between align-items-start mb-4"><div><h1 class="page-title">Requisitions</h1><p class="page-subtitle">Submit and review internal purchase requests.</p></div></div><div class="row g-4"><div class="col-lg-8"><div class="card"><div class="card-body"><table class="table align-middle"><thead><tr><th>#</th><th>Requester</th><th>Department</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($requisitions as $r): ?><tr><td><?= (int)$r['id'] ?></td><td><?= htmlspecialchars($r['requester_name']??'Unknown') ?></td><td><?= htmlspecialchars($r['department']) ?></td><td>$<?= number_format((float)$r['total_amount'],2) ?></td><td><span class="badge text-bg-<?= $r['status']==='approved'?'success':($r['status']==='rejected'?'danger':'warning') ?>"><?= htmlspecialchars($r['status']) ?></span></td><td><?php if($r['status']==='pending' && in_array(($_SESSION['user']['role'] ?? '') === 'admin' ? 'Administrator' : ($_SESSION['user']['role'] ?? ''), ['Administrator','Procurement Officer','Store Officer'], true)): ?><form method="post" action="?controller=requisition&action=decide" class="d-flex gap-1"><?= $this->csrfField() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button name="status" value="approved" class="btn btn-sm btn-success">Approve</button><button name="status" value="rejected" class="btn btn-sm btn-outline-danger">Reject</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div><div class="col-lg-4"><div class="card"><div class="card-body"><h5>New requisition</h5><form method="post" action="?controller=requisition&action=create" class="vstack gap-3"><?= $this->csrfField() ?><input class="form-control" name="department" placeholder="Department" required><input class="form-control" type="number" step="0.01" name="total_amount" placeholder="Estimated amount"><textarea class="form-control" name="remarks" placeholder="Request details"></textarea><button class="btn btn-primary">Submit request</button></form></div></div></div></div>
